-- Access and views for the city_pages schema (packages/db/README.md, "Adding tables to a
-- module"; services/city-pages/README.md). Depends on core (track_updated_at), switches
-- (switches.state) and, for callers of verify() only, run-coverage's v_search_controls and
-- v_search_coverage and audit-log's record() (not read from SQL: called from
-- @nabvy/city-pages at the application layer).
--
-- City pages and centres are pipeline data with no user rows, so there is no user_id and no RLS.
-- Only the pipeline role (nabvy_pipeline; per-module roles are question 2 of the catalogue) reads
-- and writes the tables. No delete: this module holds no listing rows, so it has nothing for
-- seller-rights erasure (rule 12); a city page or centre is only ever added, never removed.

grant usage on schema city_pages to nabvy_pipeline;
grant select, insert, update on city_pages.city_pages, city_pages.centres to nabvy_pipeline;

select nabvy_core.track_updated_at('city_pages.city_pages');
select nabvy_core.track_updated_at('city_pages.centres');

-- Great-circle distance in km (haversine, Earth radius 6371 km), for `v_area_membership` only.
-- Plain SQL, not PostGIS: no other module uses PostGIS yet, and a two-point distance needs no
-- extension. `test/domain.test.ts` proves `haversineKm` (src/domain) computes the same value.
create function city_pages.haversine_km(
  lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision
)
returns double precision
language sql
immutable
parallel safe
set search_path = pg_catalog
as $$
  select 2 * 6371 * asin(least(1, sqrt(
    sin(radians(lat2 - lat1) / 2) ^ 2
    + cos(radians(lat1)) * cos(radians(lat2)) * sin(radians(lng2 - lng1) / 2) ^ 2
  )))
$$;
revoke all on function city_pages.haversine_km(double precision, double precision, double precision, double precision) from public;
grant execute on function city_pages.haversine_km(double precision, double precision, double precision, double precision) to nabvy_pipeline;

-- Internal views: security_invoker, explicit columns, nothing seller-derived. Empty while the
-- module's switch is off (rule 11), so `details-selector` selects only shipped listings and new
-- IDs wait (README.md, "When off").

create view city_pages.v_city_pages with (security_invoker = true) as
select p.city_page_id, p.name, p.towns, p.lat, p.lng, p.coord_source, p.first_seen_at
from city_pages.city_pages p
where switches.state('city-pages') <> 'off';

create view city_pages.v_centres with (security_invoker = true) as
select
  c.city_page_id, c.active, c.verified, c.verified_by_job, c.country, c.currency,
  c.reported_lat, c.reported_lng, c.area_km
from city_pages.centres c
where switches.state('city-pages') <> 'off';

-- Nearest active centre with a resolved coordinate, and whether the city page is in its area
-- (rule: a centre's area is city pages within `area_km` of it, starting value 100 km,
-- fb-scrap-engine/README.md:117-130). A centre's coordinate is Facebook's own reported centre
-- once verified (`reported_lat`/`reported_lng`, from run-coverage's `v_search_controls`), or
-- until then the city page's own seed coordinate; a centre with neither (an unverified page
-- added with no seed coordinate) has no resolved coordinate and cannot be anyone's nearest
-- centre. A city page with no coordinate of its own (card-added) gets no row's worth of
-- distance: `centre_id` and `distance_km` are null and `in_area` is false, never guessed.
create view city_pages.v_area_membership with (security_invoker = true) as
select
  p.city_page_id,
  nearest.city_page_id as centre_id,
  nearest.distance_km,
  coalesce(nearest.distance_km <= nearest.area_km, false) as in_area
from city_pages.city_pages p
left join lateral (
  select
    c.city_page_id,
    c.area_km,
    city_pages.haversine_km(p.lat, p.lng, coalesce(c.reported_lat, cc.lat), coalesce(c.reported_lng, cc.lng))
      as distance_km
  from city_pages.centres c
  join city_pages.city_pages cc on cc.city_page_id = c.city_page_id
  where c.active
    and p.lat is not null and p.lng is not null
    and coalesce(c.reported_lat, cc.lat) is not null
    and coalesce(c.reported_lng, cc.lng) is not null
  order by distance_km asc
  limit 1
) as nearest on true
where switches.state('city-pages') <> 'off';

revoke all on city_pages.v_city_pages, city_pages.v_centres, city_pages.v_area_membership
  from public, anon, authenticated;
grant select on city_pages.v_city_pages, city_pages.v_centres, city_pages.v_area_membership
  to nabvy_pipeline;

-- Seed data for the city_pages module (services/city-pages/README.md, "Decisions").
-- Generated once from services/city-pages/city-pages.seed.json (fb-scrap-engine
-- docs/data/city-pages.seed.json, 771 rows, 5 verified) and the grid selected by
-- src/domain/selectGrid over that file's coordinates. Not regenerated by db:generate: this
-- statement is data, not a schema change.

on conflict (city_page_id) do nothing;

-- Verified centres (fb-scrap-engine/docs/EVIDENCE_LEDGER.md:32-65) plus the national grid selected
-- over the seed's coordinates, minimum separation 80 km (src/domain/selectGrid,
-- CITY_PAGES_GRID_MIN_SEPARATION_KM). Dublin is verified but inactive while the beta is UK only
-- (docs/decisions.md:19,132,137). Chichester and Glasgow have no reported centre yet: no cited
-- source gives one, so it is left null rather than invented, and an admin verification run fills
-- it in (CLAUDE.md, "No invented numbers").
--
-- The 5 verified centres: 109312942421526 Belfast, 115935195086622 Chichester,
-- 110769888951990 Dublin (inactive), 115753025103602 Edinburgh, 106233566079281 Glasgow.
-- The 23 selected grid candidates: 110092169012550 Folkestone, 111857572167033 Penzance,
-- 108640115834541 Church Stretton, 108201152541160 Scarborough, 108451039178633 Weymouth,
-- 104143249621842 Wisbech, 115432035138738 Barrow in Furness, 108305025857606 Fishguard,
-- 109347995757516 Wallingford, 108681795826032 Morpeth, 108299645860446 Sheffield,
-- 111275298897504 Barnstaple, 108055115889054 Girvan, 109352629083756 Lowestoft,
-- 108002535895476 Lancing, 103151809724379 Llandudno Junction, 104069959629600 Strathfoyle,
-- 108626969161630 Cwmbran, 107764485920251 Hinckley, 112463398769325 Braintree,
-- 112382648778727 Kingsbridge, 109804995705288 Dalbeattie, 112508092094115 Market Rasen.

on conflict (city_page_id) do nothing;
